import{_ as t}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as n,o,c as i,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/g6.md","filePath":"troubleshoot/g6.md"}'),s={name:"troubleshoot/g6.md"};function l(h,e,d,u,c,m){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="g6-one-troubleshooting" tabindex="-1">G6, ONE troubleshooting <a class="header-anchor" href="#g6-one-troubleshooting" aria-label="Permalink to &quot;G6, ONE troubleshooting&quot;">​</a></h1><p>See <a href="./../install/g6.html">how to set up G6/ONE</a> first if you haven&#39;t already. This page covers common problems once it&#39;s connected, or preventing it from connecting at all.</p><h2 id="no-connectivity-at-all" tabindex="-1">No connectivity at all <a class="header-anchor" href="#no-connectivity-at-all" aria-label="Permalink to &quot;No connectivity at all&quot;">​</a></h2><ol><li>Start from the <a href="./../install/g6.html#prerequisites">recommended settings</a> and disable engineering mode.</li><li>Communication with the transmitter happens once every 5 minutes — after changing any setting, wait for a full read cycle before judging its effect on the status page.</li><li>Make sure the transmitter is activated, and that no other phone or device is currently set to collect from it (disconnect it if there is).</li><li>Check the <a href="./systemstatus.html">Dex Status page</a>. If there&#39;s a command stuck in the queue, it should clear within the next read cycle — if it doesn&#39;t, <a href="#transmitter-queue-stuck">clear the queue</a>.</li><li>If the status page shows &quot;Deep sleeping errors&quot; or &quot;Checking Auth errors&quot; with a &quot;Last Connected&quot; time that&#39;s consistently under 5 minutes, tap <strong>Forget Device</strong> on the Classic Status page, go back to the Dex Status page, and approve the new pair request that follows (on Android 9 or older you won&#39;t get a visible prompt — it pairs automatically). If it still won&#39;t connect, <a href="#triggering-a-pair-request-manually">trigger a pair request</a> manually.</li><li>If there&#39;s no disconnect and the status page shows &quot;OK ** days&quot; for sensor status but you&#39;re getting no readings, make sure the xDrip session itself is started — tap Start Sensor and enter the calibration code shown on the status page (this doesn&#39;t affect an already-running G6 session).</li><li>If it&#39;s still not working, disable collection in xDrip, install the Dexcom app, and try it there instead. If the Dexcom app connects fine, please report it — that tells us it&#39;s an xDrip-side issue, not the transmitter.</li></ol><p>If you have connectivity and readings but it drops out occasionally, see <a href="#intermittent-connectivity">Intermittent connectivity</a> instead.</p><h2 id="intermittent-connectivity" tabindex="-1">Intermittent connectivity <a class="header-anchor" href="#intermittent-connectivity" aria-label="Permalink to &quot;Intermittent connectivity&quot;">​</a></h2><p>xDrip scans every 5 minutes to stay connected, running in the background the rest of the time to save battery. Newer Android versions (11+) and phone-manufacturer power-saving features can interfere with this, which is why initial connectivity trouble is common on recent Android.</p><ul><li>Make sure you&#39;re on at least the current stable xDrip release, and start from the <a href="./../install/g6.html#prerequisites">recommended settings</a>.</li><li>Check for phone-brand-specific guidance at <a href="https://dontkillmyapp.com/" target="_blank" rel="noreferrer">dontkillmyapp.com</a>.</li><li><strong>Pixel</strong> — disabling battery optimization needs more than &quot;Allow background usage&quot;: tap the note shown and choose <strong>Unrestricted</strong>.</li><li><strong>Xiaomi</strong> — battery optimization may silently re-enable itself after every reboot; you may need to disable it again each time.</li><li><strong>Unihertz</strong> — Android Settings → Smart Assist → Power Save Manager, and whitelist xDrip.</li><li><strong>Cubot</strong> (e.g. KingKong Mini) — open the bundled DuraSpeed app and remove xDrip from its power-saving restrictions.</li></ul><p>If disconnects continue, try these one at a time: enable Special Pairing Workaround (can help even on non-Samsung phones), try disabling Minimize Scanning, and on Samsung devices try enabling Trust Auto-Connect in <a href="./../use/bluetooth.html">Bluetooth Settings</a>.</p><h2 id="understanding-the-dex-status-page" tabindex="-1">Understanding the Dex Status page <a class="header-anchor" href="#understanding-the-dex-status-page" aria-label="Permalink to &quot;Understanding the Dex Status page&quot;">​</a></h2><p>Open it from the top-left menu → <a href="./systemstatus.html">System Status</a>, then swipe to the &quot;Dex Status&quot; page.</p><p>Connectivity is OK when: there&#39;s a &quot;Last Connected:&quot; line, its value stays under 5 minutes while you&#39;re near the phone, it climbs and rolls back to 0 every ~5-minute cycle, and there are no messages like &quot;Hunting Transmitter&quot;, &quot;Scanning Error&quot;, &quot;Waiting Connect Errors&quot;, &quot;Checking Auth Errors&quot; or &quot;Deep Sleeping Errors&quot;. Any of those messages, or a &quot;Last Connected&quot; value that doesn&#39;t behave as above, means a disconnect — resolve it before issuing any command (start, stop, calibrate, hard reset).</p><p>xDrip reflects what the transmitter reports once every 5 minutes (a sample-and-hold system), so after any change or command, give it a full cycle (or two) before drawing conclusions — don&#39;t judge by checking the status page every few seconds.</p><div class="info custom-block"><p class="custom-block-title">Picking up a session already started elsewhere</p><p>If a session is already running (started from another phone, app, or a medical device) you don&#39;t need to start a new one in xDrip — just get connectivity working as above and be patient, it can take 10–15 minutes to pick up. This doesn&#39;t apply to G7/ONE+ (those always auto-start). For G6/ONE, if the calibration code shown on the Dex Status page looks wrong or missing, ignore it — it&#39;s the transmitter that needs the correct code, not xDrip, and only matters again if you&#39;re starting a genuinely new sensor.</p></div><p>The transmitter ID shown on this page is unique to your transmitter — be careful who you share it with, and black it out of screenshots before posting them for help; no one needs to see it to help you.</p><h2 id="sensor-wont-start-sensor-failed-messages" tabindex="-1">Sensor won&#39;t start / &quot;sensor failed&quot; messages <a class="header-anchor" href="#sensor-wont-start-sensor-failed-messages" aria-label="Permalink to &quot;Sensor won&#39;t start / &quot;sensor failed&quot; messages&quot;">​</a></h2><p>Most of these come down to the transmitter not being confident this is a genuine new sensor start:</p><ul><li>The transmitter must be out of any sensor for at least <strong>10 minutes</strong> before you start a new one. A common mistake is applying the new sensor while the old one is still running, stopping the old one, and immediately snapping the transmitter into the new sensor — since it was never out for 10 minutes, the transmitter treats it as a restart attempt and fails the new sensor with an error.</li><li>Make sure you have <a href="#understanding-the-dex-status-page">proper connectivity</a> before attempting to start — if you don&#39;t, resolve that first rather than retrying start/stop.</li><li>If you get a &quot;sensor start failed&quot; message, wait it out rather than repeatedly retrying — repeated attempts without addressing the underlying connectivity or timing issue tend to make it worse.</li></ul><h2 id="transmitter-queue-stuck" tabindex="-1">Transmitter queue stuck <a class="header-anchor" href="#transmitter-queue-stuck" aria-label="Permalink to &quot;Transmitter queue stuck&quot;">​</a></h2><p>The transmitter is only listening for a brief moment once every 5 minutes; the rest of the time it&#39;s silent to save battery. Any command you issue (Start Sensor, Stop Sensor, Calibrate) sits in a queue until the next window — you&#39;ll see it listed on the Dex Status page. As long as it&#39;s listed, the transmitter hasn&#39;t received it yet, so don&#39;t issue another command on top of it, and especially don&#39;t issue commands while you don&#39;t have proper connectivity — you can end up locked out entirely.</p><p>If a command has been sitting in the queue for longer than 5 minutes and you can&#39;t establish connectivity, clear it:</p><ol><li>Tap the dropper (treatment) symbol on the main screen.</li><li>Long-press the microphone icon at the bottom right to get a text entry field instead of voice input.</li><li>Type <code>clear transmitter queue</code> and confirm.</li></ol><p>Don&#39;t clear the queue just because a command is sitting there normally after you issued it — that&#39;s expected and clearing it would stop the command from ever being applied.</p><h2 id="triggering-a-pair-request-manually" tabindex="-1">Triggering a pair request manually <a class="header-anchor" href="#triggering-a-pair-request-manually" aria-label="Permalink to &quot;Triggering a pair request manually&quot;">​</a></h2><ol><li>Settings → Dexcom Transmitter ID. Note the current value (write it down or screenshot it).</li><li>Change the last character to anything else and apply.</li><li>Change it back to the correct value and apply.</li><li>Go to the <a href="./systemstatus.html">Dex Status page</a> — you should see &quot;Hunting Transmitter&quot; in red.</li><li>Within 5 minutes you should get a pair request on Android 10+ — approve it. On Android 9 or older, it pairs automatically with no visible prompt.</li><li>If your screen is locked when the request notification arrives, unlock it, pull down the notification shade, and approve it from there.</li></ol><h2 id="how-strong-is-the-transmitter-signal" tabindex="-1">How strong is the transmitter signal? <a class="header-anchor" href="#how-strong-is-the-transmitter-signal" aria-label="Permalink to &quot;How strong is the transmitter signal?&quot;">​</a></h2><p>If the transmitter isn&#39;t actually broadcasting, no xDrip configuration will fix that — a Bluetooth scanner lets you check independently of xDrip.</p><ol><li>Install a continuously-scanning Bluetooth scanner app (e.g. &quot;BLE Scanner&quot;) on any Android phone — it doesn&#39;t need to be the one running xDrip. Watch out for on-screen ads in these apps.</li><li>Grant the permissions it asks for, keep the transmitter in the same room, and let it scan.</li><li>Look for a device named <code>Dexcom**</code> (last two characters of the transmitter&#39;s serial number) for G6/ONE, or <code>DXCM**</code>/<code>DX02**</code>/<code>DX04**</code> (random suffix) for G7/ONE+.</li><li>Note the negative signal-strength number next to it — you may need to wait up to 5 minutes for a bold (current) listing to appear.</li><li>If it never appears, the transmitter isn&#39;t transmitting at all. If it does, report the device name and the number to whoever is helping you debug.</li></ol><h2 id="how-good-is-the-battery" tabindex="-1">How good is the battery? <a class="header-anchor" href="#how-good-is-the-battery" aria-label="Permalink to &quot;How good is the battery?&quot;">​</a></h2><p>Transmitter batteries degrade in storage even when unused — that&#39;s why the box shows both a manufacture date and an expiry date. On the <a href="./systemstatus.html">Dex Status page</a> you&#39;ll see two voltages, Voltage A and Voltage B. They vary between individual transmitters, but as a battery nears end of life, Voltage B starts a steady, continuous decline — worth keeping an eye on over a transmitter&#39;s life if readings start looking unreliable near the expected end of its battery life.</p><h2 id="transmitter-warranty" tabindex="-1">Transmitter warranty <a class="header-anchor" href="#transmitter-warranty" aria-label="Permalink to &quot;Transmitter warranty&quot;">​</a></h2><p>A transmitter is under warranty if both are true: the Use-By/Ship-By date on the box hadn&#39;t passed when you started (or received) it, and you started using it within 5 months of receiving it. Coverage is for 90 uninterrupted days of proper operation. Because of this, it&#39;s not worth stockpiling transmitters — the battery ages regardless, and the warranty clock can run out before you get to use a spare.</p><h2 id="hard-reset" tabindex="-1">Hard reset <a class="header-anchor" href="#hard-reset" aria-label="Permalink to &quot;Hard reset&quot;">​</a></h2><p>G6 can be hard reset through xDrip only if its firmware is 1.6.5.25 or earlier — newer firmware can&#39;t be hard reset this way. A hard reset zeroes the transmitter&#39;s day counter on the status page; do it only while there&#39;s no active session (e.g. after stopping a sensor, before starting the next one).</p><ol><li>Confirm you have proper connectivity to the transmitter, and disable the Dexcom app (xDrip and Dexcom app can&#39;t both collect from the same transmitter).</li><li>On the main screen, tap the dropper (treatment) symbol.</li><li>Long-press the microphone icon at the bottom right to get a text field.</li><li>Type <code>Hard Reset Transmitter</code> and confirm — you&#39;ll see a message that the attempt will be made. Don&#39;t close xDrip; the command still needs to reach the transmitter.</li><li>Watch the status page — it can take up to 5 minutes to submit. You may see a warning that it may have failed; if so, restart your phone or force-stop and restart xDrip.</li><li>Remove the transmitter from Android&#39;s list of previously connected Bluetooth devices.</li></ol><p>If you intend to keep using the transmitter afterward, activate it again as if it were brand new.</p><h2 id="restarting-a-sensor-beyond-its-normal-session" tabindex="-1">Restarting a sensor beyond its normal session <a class="header-anchor" href="#restarting-a-sensor-beyond-its-normal-session" aria-label="Permalink to &quot;Restarting a sensor beyond its normal session&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Read this whole section before attempting it</p><p>Restarting is not approved by the manufacturer and carries real risk. Readings will be significantly (and predictably) too high right after the restart&#39;s warm-up — if you correct that with insulin, or run a closed loop without opening it first, you can cause hypoglycemia.</p></div><p>If the transmitter&#39;s firmware (shown on the Dex Status page) is 1.6.5.25 or earlier, you can use xDrip&#39;s preemptive restart instead and skip all of this — it restarts the sensor for you automatically. Otherwise, if you want to keep the <em>same</em> sensor running past its normal 10-day session, this is how, using the original calibration code (attempting a no-code restart has more reports of malfunction):</p><ol><li>Make sure connectivity is solid first — restarting won&#39;t fix an underlying connectivity problem, and you don&#39;t have to restart before day 10 anyway, only if you choose to.</li><li>Tap Stop Sensor (top-left menu), even if it&#39;s already stopped and Stop Sensor is the only option shown. Wait for it to clear the queue on the status page (~5 minutes) before continuing — you&#39;ll then see &quot;Sensor: Stopped&quot;.</li><li><a href="#removing-a-transmitter-without-damaging-the-sensor">Remove the transmitter without damaging the sensor</a>.</li><li>Wait at least 10 minutes with the transmitter out.</li><li>Snap the transmitter back in and Start Sensor, entering the <em>original</em> calibration code again.</li></ol><p>After the 2-hour warm-up, expect readings to run significantly high — this is because the transmitter now thinks it&#39;s on day 1 of a fresh sensor, when your body&#39;s actual response to the sensor is that of a several-days-old one. You&#39;ll need to calibrate carefully: correct by no more than 20% at a time, spacing calibrations at least 25 minutes apart (45 for a third), and only while the trend is flat — otherwise you risk a confused calibration error. You&#39;ll see &quot;Received backfill packet out of sequence&quot; in the logs during this; that&#39;s expected and can be ignored. As with any aging sensor, keep checking against a glucose meter occasionally afterward.</p><h2 id="changing-the-bluetooth-slot-advanced-not-recommended" tabindex="-1">Changing the Bluetooth slot (advanced, not recommended) <a class="header-anchor" href="#changing-the-bluetooth-slot-advanced-not-recommended" aria-label="Permalink to &quot;Changing the Bluetooth slot (advanced, not recommended)&quot;">​</a></h2><p>A G6 transmitter has two communication slots — that&#39;s how you can use a t:slim pump <em>and</em> see readings in xDrip, or use a Dexcom receiver and xDrip together. xDrip defaults to slot 2; a t:slim pump and the Dexcom receiver both use slot 1.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This setting is still behind engineering mode because testing has produced unexpected results, including transmitters that were permanently disabled. It&#39;s not currently recommended.</p></div><p>If you still want to change it: enable <a href="./../use/misc.html#engineering-mode">engineering mode</a>, then Settings → Dex Debug Settings → &quot;Manual Slot Number&quot;, and set it to <code>1</code> to force the non-default slot (disabling engineering mode reverts to the default). Two collector apps using the two different slots can&#39;t run on the same phone.</p><h2 id="removing-a-transmitter-without-damaging-the-sensor" tabindex="-1">Removing a transmitter without damaging the sensor <a class="header-anchor" href="#removing-a-transmitter-without-damaging-the-sensor" aria-label="Permalink to &quot;Removing a transmitter without damaging the sensor&quot;">​</a></h2><p>Normally, once you peel off a sensor you open it up, take the transmitter out, and throw the sensor away. This is how to remove the transmitter while leaving the sensor intact and still on your body, e.g. to move it to a fresh sensor.</p><p>Don&#39;t touch the contacts on either the transmitter or the sensor while doing this.</p><p>The sensor has two prongs that latch onto the sides of the transmitter, held under spring pressure by the flexible material inside the sensor housing. To release them, you need something thin and sturdy to gently push each prong away from the transmitter — cut a small strip from the plastic packaging of a spare sensor and round its corners with scissors to make a simple tool (keep it away from children or pets — it&#39;s a choking hazard in small hands).</p><p>Gently insert the wider, rounded end of the strip between the sensor and the transmitter, right where a prong is, until you feel or hear it click and release. The compressed material inside then pushes the transmitter away on that side by itself — you don&#39;t need to pry further, just avoid pressing down on top of the transmitter, which would re-seat it. Repeat on the other side, and the transmitter lifts free.</p><h2 id="what-not-to-do" tabindex="-1">What not to do <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;What not to do&quot;">​</a></h2><ul><li>Don&#39;t remove a transmitter from its box, or touch its contacts, before you&#39;re ready to use it — the day counter starts immediately and can&#39;t be paused.</li><li>Don&#39;t throw away a sensor&#39;s adhesive cover before noting the calibration code printed on it.</li><li>Don&#39;t pre-soak a sensor (inserting it well before starting it in xDrip) — it interferes with factory calibration.</li><li>Don&#39;t start a sensor unless the transmitter has been out of any sensor for at least 10 minutes first.</li><li>Don&#39;t correct more than 20% of a reading in a single calibration.</li><li>Don&#39;t stop a sensor just because you think you can easily restart it — there&#39;s almost always a better option than stopping.</li><li>When you switch phones, remember to disable collection on the old one, or both phones will fight over the connection.</li><li>Don&#39;t attempt a <a href="#restarting-a-sensor-beyond-its-normal-session">restart</a> without understanding and accepting the risks — it isn&#39;t manufacturer-approved and readings will be wrong for a while afterward.</li></ul><h2 id="ob1-debugging-logs" tabindex="-1">OB1 debugging logs <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;OB1 debugging logs&quot;">​</a></h2><p>This applies to G6, ONE, G7 and ONE+ alike: they all use the same OB1 collector, which stores very little log detail by default. If a developer asks you for detailed logs while troubleshooting a connection issue, enable full OB1 logging first.</p><p>The easiest way is to scan this QR code with Settings, <a href="./../use/copysettings.html#auto-configure">Auto configure</a> and approve the import prompt. It only sets one preference, Extra tags for logging.</p><p>QR Code - Click image to expand</p><p><a href="./images/qr_ob1_debug.png"><img src="'+t+'" style="zoom:50%;"></a></p><p>You can also enter the tags by hand:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Extra Logging Settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Extra tags for logging</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Then:</p><ul><li>Wait for the problem to actually happen before uploading. Enabling logging alone captures nothing useful yet.</li><li>Open the <a href="./../use/3dotsmenu.html#events-log">Events Log</a> from the 3 dots menu, tap Upload Logs, and add a note identifying the device so it can be matched up when you report it.</li><li>Disable it afterwards: clear the Extra tags for logging field and confirm. Otherwise it keeps generating a lot of extra log volume.</li></ul>',62)])])}const b=n(s,[["render",l]]);export{y as __pageData,b as default};
